/* From Uiverse.io by Javierrocadev - Tags: card, box-shadow */
.__UIV_SCOPE__ .card {
  width: 150px;
  height: 150px;
  background: #a53c3c;
  border-radius: 5px;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  font-size: 3em;
  font-weight: 900;
  color: aliceblue;
  transition: all .5s ease-in-out;
}

.__UIV_SCOPE__ .text {
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 75px 75px 5px -20px #bf5e37, -75px 75px 5px -20px #d08432, -75px -75px 5px -20px #bf5e37 , 75px -75px 5px -20px #d08432;
  transform: rotate(-45deg);
}

.__UIV_SCOPE__ .card:hover .text {
  transform: rotate(45deg);
}
